180	  _append(str: string, maybeNewline: boolean): void {
181	    const len = str.length;
182	    const position = this._position;
183	    const sourcePos = this._sourcePosition;
184	
185	    this._last = -1; /* LAST_CHAR_KINDS.NORMAL */
186	
187	    if (++this._appendCount > 4096) {
