218	    // ok. It's also unclear how other sourcemap utilities handle them...
219	    let i = str.indexOf("\n");
220	    let last = 0;
221	
222	    // If the string starts with a newline char, then adding a mark is redundant.
223	    // This catches both "no newlines" and "newline after several chars".
224	    if (hasMap && i !== 0) {
225	      this._map!.mark(
226	        position,
227	        line,
228	        column,
229	        identifierName,
230	        identifierNamePos,
231	        filename,
232	      );
233	    }
234	
235	    // Now, find each remaining newline char in the string.
236	    while (i !== -1) {
237	      position.line++;
238	      position.column = 0;
239	      last = i + 1;
240	
241	      // We mark the start of each line, which happens directly after this newline char
242	      // unless this is the last char.
243	      // When manually adding multi-line content (such as a comment), `line` will be `undefined`.
244	      if (last < len && line !== undefined) {
245	        line++;
246	        if (hasMap) {
247	          this._map!.mark(position, line, 0, undefined, undefined, filename);
248	        }
249	      }
250	      i = str.indexOf("\n", last);
251	    }
252	    position.column += len - last;
