281	  /**
282	   * Certain sourcemap usecases expect mappings to be more accurate than
283	   * Babel's generic sourcemap handling allows. For now, we special-case
284	   * identifiers to allow for the primary cases to work.
285	   * The goal of this line is to ensure that the map output from Babel will
286	   * have an exact range on identifiers in the output code. Without this
287	   * line, Babel would potentially include some number of trailing tokens
288	   * that are printed after the identifier, but before another location has
289	   * been assigned.
290	   * This allows tooling like Rollup and Webpack to more accurately perform
291	   * their own transformations. Most importantly, this allows the import/export
292	   * transformations performed by those tools to loose less information when
293	   * applying their own transformations on top of the code and map results
294	   * generated by Babel itself.
295	   *
296	   * The primary example of this is the snippet:
297	   *
298	   *   import mod from "mod";
299	   *   mod();
300	   *
301	   * With this line, there will be one mapping range over "mod" and another
302	   * over "();", where previously it would have been a single mapping.
303	   */
304	  exactSource(loc: Loc, cb: () => void) {
305	    if (!this._map) {
306	      cb();
307	      return;
308	    }
309	
310	    this.source("start", loc);
311	    const identifierName = loc.identifierName;
312	    const sourcePos = this._sourcePosition;
313	    if (identifierName != null) {
314	      this._canMarkIdName = false;
315	      sourcePos.identifierName = identifierName;
316	    }
317	    cb();
318	
319	    if (identifierName != null) {
320	      this._canMarkIdName = true;
321	      sourcePos.identifierName = undefined;
322	      sourcePos.identifierNamePos = undefined;
323	    }
324	    this.source("end", loc);
325	  }
