329	   * will be given this position in the sourcemap.
330	   */
331	
332	  source(prop: "start" | "end", loc: Loc): void {
333	    if (!this._map) return;
334	
335	    // Since this is called extremely often, we reuse the same _sourcePosition
336	    // object for the whole lifetime of the buffer.
337	    this._normalizePosition(prop, loc, 0);
338	  }
339	
340	  sourceWithOffset(
341	    prop: "start" | "end",
342	    loc: Loc,
343	    columnOffset: number,
344	  ): void {
345	    if (!this._map) return;
346	
347	    this._normalizePosition(prop, loc, columnOffset);
348	  }
349	
350	  _normalizePosition(prop: "start" | "end", loc: Loc, columnOffset: number) {
351	    this._flush();
352	
353	    const pos = loc[prop];
354	    const target = this._sourcePosition;
355	
356	    if (pos) {
357	      target.line = pos.line;
358	      // TODO: Fix https://github.com/babel/babel/issues/15712 in downstream
359	      target.column = Math.max(pos.column + columnOffset, 0);
360	      target.filename = loc.filename;
361	    }
362	  }
363	
364	  getCurrentColumn(): number {
365	    return this._position.column + (this._queuedChar ? 1 : 0);
366	  }
367	
368	  getCurrentLine(): number {
369	    return this._position.line;
370	  }
371	}
